# Let us test standard CRC-32 algorithms on body and body[4:]
CRCS = [
    # (poly, init, refin, refout, xorout)
    ("CRC-32/ISO-HDLC", 0x04C11DB7, 0xFFFFFFFF, True, True, 0xFFFFFFFF),
    ("CRC-32/BZIP2", 0x04C11DB7, 0xFFFFFFFF, False, False, 0xFFFFFFFF),
    ("CRC-32/MPEG-2", 0x04C11DB7, 0xFFFFFFFF, False, False, 0x00000000),
    ("CRC-32/POSIX", 0x04C11DB7, 0x00000000, False, False, 0xFFFFFFFF),
    ("CRC-32/JAMCRC", 0x04C11DB7, 0xFFFFFFFF, True, True, 0x00000000),
    ("CRC-32/XFER", 0x000000AF, 0x00000000, False, False, 0x00000000),
    ("CRC-32C", 0x1EDC6F41, 0xFFFFFFFF, True, True, 0xFFFFFFFF),
    ("CRC-32D", 0xA833982B, 0xFFFFFFFF, True, True, 0xFFFFFFFF),
    ("CRC-32Q", 0x814141AB, 0x00000000, False, False, 0x00000000),
    ("CRC-32/AUTOSAR", 0xF4ACFB13, 0xFFFFFFFF, True, True, 0xFFFFFFFF),
    ("CRC-32/CD-ROM-EDC", 0x80018001, 0x00000000, True, True, 0x00000000),
]

def reflect(val, bits):
    return int(f"{val:0{bits}b}"[::-1], 2)

def compute_crc(data, poly, init, refin, refout, xorout):
    reg = init
    for b in data:
        if refin:
            b = reflect(b, 8)
        reg ^= (b << 24)
        for _ in range(8):
            if reg & 0x80000000:
                reg = ((reg << 1) ^ poly) & 0xFFFFFFFF
            else:
                reg = (reg << 1) & 0xFFFFFFFF
    if refout:
        reg = reflect(reg, 32)
    return reg ^ xorout

with open("/app/samples/s06_empty.jrn", "rb") as f:
    data = f.read()

for slice_data, label in [(data[:-4], "all"), (data[4:-4], "no_magic")]:
    for name, poly, init, refin, refout, xorout in CRCS:
        c = compute_crc(slice_data, poly, init, refin, refout, xorout)
        stored_be = int.from_bytes(data[-4:], "big")
        stored_le = int.from_bytes(data[-4:], "little")
        if c == stored_be or c == stored_le:
            print(f"MATCH! {name} {label}: {hex(c)}")
print("Done checking common CRCs")
'

